import { Component, input } from '@angular/core';
import { NzDividerModule } from 'ng-zorro-antd/divider';

/** hrm-divider — đường kẻ phân cách, bọc nz-divider. */
@Component({
  selector: 'hrm-divider',
  imports: [NzDividerModule],
  template: `
    <nz-divider
      [nzText]="text()"
      [nzOrientation]="orientation()"
      [nzType]="type()"
      [nzDashed]="dashed()"></nz-divider>
  `,
  host: { class: 'hrm-divider' },
})
export class HrmDivider {
  readonly text = input('');
  readonly orientation = input<'left' | 'right' | 'center'>('center');
  readonly type = input<'horizontal' | 'vertical'>('horizontal');
  readonly dashed = input(false);
}
